static int32_t __stdcall QUESTLOG_HitTestActTab(uint32_t nY, uint32_t nX) {
    int nTabIndex;
    int nTabY;
    if (!(nY <= 0x1b && nX <= 0x13f)) {
      return -1;
    }

    BOOL bIsExpansion = Fog::D2CheckExpansionGame();
    if (bIsExpansion) {
      bIsExpansion = GAME::Game::CLIENT_CheckExpansion();
      if (bIsExpansion) {
        nTabIndex = 0;
        nTabY = 0;
        while ((int)nX < nTabY || (int)nX > nTabY + 0x40) {
          nTabY += 0x40;
          nTabIndex++;
          if (nTabY >= 0x140) {
            return -1;
          }
        }

        return nTabIndex;
      }
    }

    nTabIndex = 0;
    nTabY = 0;
    do {
      if ((int)nX >= nTabY && (int)nX <= nTabY + 0x50) {
        return nTabIndex;
      }

      nTabY += 0x50;
      nTabIndex++;
    } while (nTabY < 0x140);

    return -1;
}

void __fastcall QUESTLOG_AcknowledgeNewQuests(int32_t nAct) {
    D2BitBufferStrc* pBitBuffer;
    int nIndex = 0;
    if (gQuestLog.nQuestLogQuestCount <= 0) {
      return;
    }

    int32_t* pQuestEntry = &gQuestLog.aQuestLogEntries[0].eQuestId;
    do {
      if (!*(uint32_t*)((char*)pQuestEntry + 0x265)) {
        pBitBuffer = npcmenu::GetQuestInfo();
        D2Common::QuestRecord::SetQuestState(pBitBuffer, *pQuestEntry, QUESTSTATE_BoxGrayed);
        GAME::Msg::NET_D2GS_CLIENT_Send_SHORT('X', (short int)*pQuestEntry);
      }

      nIndex++;
      pQuestEntry = (int32_t*)((char*)pQuestEntry + 0x26a);
    } while (nIndex < gQuestLog.nQuestLogQuestCount);
}

