static void QUESTLOG_ShowQuestDescription(uint32_t nActIndex) {
    int nIndex = 0;
    if (gQuestLog.nQuestLogQuestCount <= 0) {
      return;
    }

    uint8_t* pQuestEntry = &gQuestLog.aQuestLogEntries[0].nQuestTableIndex;
    while (*pQuestEntry != nActIndex) {
      nIndex++;
      pQuestEntry += 0x26a;
      if (nIndex < gQuestLog.nQuestLogQuestCount) {
        continue;
      }

      return;
    }

    if (nIndex == -1) {
      return;
    }

    uint16_t nDescStringId = gQuestLog.aQuestLogEntries[nIndex].wDescStringId;
    if (!(nDescStringId != 0xe8c && nDescStringId != 0xe8d)) {
      return;
    }

    Text::TEXT_ShowScrollingText(nDescStringId, 1, 0);
    Text::TEXT_SetScrollCompleteCallback(QUESTLOG_ScrollCompleteCallback_ClearButton, nullptr);
    gQuestLog.bQuestLogButtonDown = 1;
}

